    #include <iostream>
using namespace std;

// A linked list node 
struct Node {
    int data;
    Node* next;

    Node(int x) {
        data = x;
        next = NULL;
    }
};

// Function to pairwise swap nodes 
Node* pairwiseSwap(Node* head)
{
    // Handle base cases 
    if (head == NULL || head->next == NULL)
        return head;

    // Initialize pointers for 
    // first node of pair and second node of pair
    Node* prev = head;         
    Node* curr = head->next;  

    // Update head to second node (after first swap)
    head = curr;

    // Traverse list in pairs
    while (true) {

        // Store next pair starting node
        Node* next = curr->next;

        // Perform swap of current pair
        curr->next = prev;

        // If no more pairs OR only one node left
        if (next == NULL || next->next == NULL) {

            // connect remaining node (if exists)
            prev->next = next;
            break;
        }

        // Connect current swapped pair to next swapped pair
        prev->next = next->next;

        // Move pointers to next pair
        prev = next;
        curr = prev->next;
    }

    // Step 10: Return new head
    return head;
}

// Print in required format 
void printList(Node* node)
{
    while (node != NULL) {
        cout << node->data;
        if (node->next != NULL)
            cout << " -> ";

        node = node->next;
    }
}

// Driver code 
int main()
{
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);
    head->next->next->next->next = new Node(5);
    head = pairwiseSwap(head);
    printList(head);
    return 0;
}


